-- Sample instructions for testing
-- This file can be executed to add sample instructions to existing exam sets

INSERT INTO `instructions_one` (`exam_set_id`, `title_english`, `instruction_english`, `title_hindi`, `instruction_hindi`) VALUES
(1, 'General Instructions', 
'<p><strong>Welcome to the Online Examination</strong></p><p>1. Read all questions carefully before attempting.</p><p>2. Each question carries equal marks.</p><p>3. There is no negative marking.</p><p>4. You have 60 minutes to complete this exam.</p><p>5. Click "Submit" when you are done.</p><p><em>Best of luck!</em></p>', 
'सामान्य निर्देश', 
'<p><strong>ऑनलाइन परीक्षा में आपका स्वागत है</strong></p><p>1. प्रश्नों को हल करने से पहले सभी प्रश्नों को ध्यान से पढ़ें।</p><p>2. प्रत्येक प्रश्न के लिए समान अंक हैं।</p><p>3. कोई नकारात्मक अंकन नहीं है।</p><p>4. इस परीक्षा को पूरा करने के लिए आपके पास 60 मिनट हैं।</p><p>5. जब आप पूरा कर लें तो "जमा करें" पर क्लिक करें।</p><p><em>शुभकामनाएं!</em></p>'),

(2, 'Exam Guidelines', 
'<p><strong>Important Instructions</strong></p><p>1. This is a timed examination.</p><p>2. All questions are mandatory.</p><p>3. Use only the provided tools and resources.</p><p>4. Do not refresh the browser during the exam.</p><p>5. Your progress will be saved automatically.</p><p>Good luck with your examination!</p>', 
'परीक्षा दिशानिर्देश', 
'<p><strong>महत्वपूर्ण निर्देश</strong></p><p>1. यह एक समयबद्ध परीक्षा है।</p><p>2. सभी प्रश्न अनिवार्य हैं।</p><p>3. केवल प्रदान किए गए उपकरण और संसाधनों का उपयोग करें।</p><p>4. परीक्षा के दौरान ब्राउज़र को रीफ्रेश न करें।</p><p>5. आपकी प्रगति स्वचालित रूप से सहेजी जाएगी।</p><p>आपकी परीक्षा के लिए शुभकामनाएं!</p>');